create or replace function public.create_service_order(target_ticket_id uuid,target_contract_id uuid default null,target_location_id uuid default null,target_technician_id uuid default null,target_supplier_id uuid default null,target_scheduled_at timestamptz default null)
returns uuid language plpgsql security definer set search_path=public as $$ declare ticket public.tickets%rowtype; order_id uuid; begin select * into ticket from public.tickets where id=target_ticket_id for update; if ticket.id is null or not public.has_organization_role(ticket.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'SERVICE_ORDER_NOT_AUTHORIZED'; end if; insert into public.service_orders(organization_id,ticket_id,contract_id,location_id,technician_id,supplier_id,scheduled_at,created_by,updated_by) values(ticket.organization_id,ticket.id,target_contract_id,target_location_id,target_technician_id,target_supplier_id,target_scheduled_at,auth.uid(),auth.uid()) returning id into order_id; insert into public.service_order_events(service_order_id,organization_id,event_type,actor_id) values(order_id,ticket.organization_id,'CREATED',auth.uid()); insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,source) values(ticket.organization_id,auth.uid(),'SERVICE_ORDER_CREATED','service_order',order_id,'WEB'); return order_id; end; $$;
create or replace function public.dispatch_service_order(target_order_id uuid,target_technician_id uuid,target_scheduled_at timestamptz default null) returns void language plpgsql security definer set search_path=public as $$ declare order_record public.service_orders%rowtype; begin select * into order_record from public.service_orders where id=target_order_id for update; if order_record.id is null or not public.has_organization_role(order_record.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER','DISPATCHER']::public.platform_role[]) then raise exception 'SERVICE_ORDER_NOT_AUTHORIZED'; end if; if order_record.status not in('TRIAGE','DISPATCHED') then raise exception 'SERVICE_ORDER_INVALID_STATE'; end if; if not exists(select 1 from public.technicians where id=target_technician_id and organization_id=order_record.organization_id and active) then raise exception 'SERVICE_ORDER_INVALID_TECHNICIAN'; end if; update public.service_orders set technician_id=target_technician_id,scheduled_at=coalesce(target_scheduled_at,scheduled_at),status='DISPATCHED',dispatched_at=clock_timestamp(),updated_by=auth.uid() where id=order_record.id; insert into public.service_order_events(service_order_id,organization_id,event_type,actor_id) values(order_record.id,order_record.organization_id,'DISPATCHED',auth.uid()); end; $$;
revoke all on function public.create_service_order(uuid,uuid,uuid,uuid,uuid,timestamptz),public.dispatch_service_order(uuid,uuid,timestamptz) from public; grant execute on function public.create_service_order(uuid,uuid,uuid,uuid,uuid,timestamptz),public.dispatch_service_order(uuid,uuid,timestamptz) to authenticated;
